import { and, eq, inArray } from "drizzle-orm";
import { db } from "@/db";
import { courses, lessonMedia, mediaAssets, users } from "@/db/schema";
import { deleteStoredObject } from "@/server/storage";

export type StoredMediaAsset = Pick<
  typeof mediaAssets.$inferSelect,
  "id" | "uploaderId" | "storageKey"
>;

export function mediaAccessPath(assetId: string): string {
  return `/api/v1/media/access?assetId=${assetId}`;
}

/** Extract only the asset-id format generated by this application. */
export function mediaAssetIdFromAccessUrl(value: string | null): string | null {
  if (!value) return null;
  try {
    const url = new URL(value, "https://media.local");
    if (url.pathname !== "/api/v1/media/access") return null;
    const assetId = url.searchParams.get("assetId")?.trim();
    return assetId || null;
  } catch {
    return null;
  }
}

export interface MediaCleanupResult {
  deletedIds: string[];
  skippedIds: string[];
  failedIds: string[];
}

/**
 * Permanently removes unreferenced assets and their stored bytes.
 *
 * Database mutations detach media first. This helper then checks every way an
 * asset can still be used (lesson, course cover, or profile photo) before it
 * deletes the object. Shared assets are therefore never removed prematurely.
 */
export async function cleanupMediaAssets(
  assets: StoredMediaAsset[],
): Promise<MediaCleanupResult> {
  const unique = [...new Map(assets.map((asset) => [asset.id, asset])).values()];
  const result: MediaCleanupResult = { deletedIds: [], skippedIds: [], failedIds: [] };
  if (unique.length === 0) return result;

  const ids = unique.map((asset) => asset.id);
  const [lessonRefs, coverRefs, avatarRefs] = await Promise.all([
    db
      .select({ assetId: lessonMedia.assetId })
      .from(lessonMedia)
      .where(inArray(lessonMedia.assetId, ids)),
    db
      .select({ assetId: courses.coverAssetId })
      .from(courses)
      .where(inArray(courses.coverAssetId, ids)),
    db
      .select({ avatarUrl: users.avatarUrl })
      .from(users)
      .where(inArray(users.avatarUrl, ids.map(mediaAccessPath))),
  ]);

  const referenced = new Set<string>([
    ...lessonRefs.map((row) => row.assetId),
    ...coverRefs.map((row) => row.assetId).filter((id): id is string => Boolean(id)),
    ...avatarRefs
      .map((row) => mediaAssetIdFromAccessUrl(row.avatarUrl))
      .filter((id): id is string => Boolean(id)),
  ]);

  for (const asset of unique) {
    if (referenced.has(asset.id)) {
      result.skippedIds.push(asset.id);
      continue;
    }
    try {
      await deleteStoredObject(asset.storageKey);
      await db
        .delete(mediaAssets)
        .where(and(eq(mediaAssets.id, asset.id), eq(mediaAssets.uploaderId, asset.uploaderId)));
      result.deletedIds.push(asset.id);
    } catch (error) {
      // Keep the unattached database row when storage deletion fails so a later
      // course cleanup can retry; never report the object as deleted.
      result.failedIds.push(asset.id);
      console.error(`[media] Could not delete stored object for asset ${asset.id}:`, error);
    }
  }
  return result;
}
